 * Named candidates are retained so arithmetic and opcode selection are easy
 * to correlate in a VCD. All output data is derived directly from a and b.
 */
module alu8 (
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [2:0] op,
    output reg  [7:0] result
);

    /* Explicit 9-bit operands preserve carry and subtraction range. */
    wire [8:0] a_u9;
    wire [8:0] b_u9;
    wire [8:0] add9;
    wire [8:0] diff9;

    /* Named bitwise candidates support waveform-level opcode auditing. */
    wire [7:0] and_result;
    wire [7:0] or_result;
    wire [7:0] xor_result;

    assign a_u9 = {1'b0, a};
    assign b_u9 = {1'b0, b};
    assign add9 = a_u9 + b_u9;
    assign diff9 = a_u9 - b_u9;

    assign and_result = a & b;
    assign or_result  = a | b;
    assign xor_result = a ^ b;

