        result = 8'h00;
        case (op)
            3'b000: result = add9[7:0];
            3'b001: result = diff9[7:0];
            3'b010: result = and_result;
            3'b011: result = or_result;
            3'b100: result = xor_result;
            3'b101: result = 8'h00;
            3'b110: result = 8'h00;
            3'b111: result = 8'h00;
            default: result = 8'h00;
        endcase
    end

