import json
import os
import random

import cocotb
from cocotb.triggers import Timer

# WARNING: model wrapper unavailable; TB-local reference may drift from the
# block model. The alu8 uArch explicitly states that no Python golden model
# exists and designates its Section 2 opcode equations as the reference.
try:
    from alu8_model import alu8 as _golden_alu8
except ImportError:
    _golden_alu8 = None


_DV_SEED = int(os.environ.get("CORESMITH_DV_SEED", "0"), 0)
_MASK8 = 0xFF
_SETTLE_NS = 1
_CONTEXT_CLOCK_PERIOD_NS = 20


def _spec_reference(a: int, b: int, op: int) -> int:
    """Last-resort oracle: exact equations designated by uArch Section 2."""
    a = int(a) & _MASK8
    b = int(b) & _MASK8
    op = int(op) & 0x7

    if op == 0:
        return (a + b) & _MASK8
    if op == 1:
        return (a - b) & _MASK8
    if op == 2:
        return a & b
    if op == 3:
        return a | b
    if op == 4:
        return a ^ b
    return 0


def _model_result(a: int, b: int, op: int) -> int:
    a = int(a) & _MASK8
    b = int(b) & _MASK8
    op = int(op) & 0x7
    if _golden_alu8 is not None:
        return int(_golden_alu8(a, b, op)) & _MASK8
    return _spec_reference(a, b, op)


async def _drive_and_check(dut, a: int, b: int, op: int, *, context: str) -> int:
    a = int(a) & _MASK8
    b = int(b) & _MASK8
    op = int(op) & 0x7
    expected = _model_result(a, b, op)

    dut.a.value = int(a)
    dut.b.value = int(b)
    dut.op.value = int(op)
    await Timer(_SETTLE_NS, unit="ns")

    actual = int(dut.result.value)
    assert actual == expected, (
        f"{context}: a=0x{a:02x}, b=0x{b:02x}, op=0b{op:03b}, "
        f"expected=0x{expected:02x}, actual=0x{actual:02x}"
    )
    return actual


@cocotb.test()
async def test_reset_equivalent_idle(dut):
    """The reset-less stateless DUT must be deterministic from time zero."""
    await _drive_and_check(dut, 0, 0, 0, context="time-zero zero inputs")
    for op in (5, 6, 7):
        await _drive_and_check(
            dut,
            0xFF,
            0xA5,
            op,
            context=f"time-zero equivalent reserved opcode {op}",
        )


@cocotb.test()
async def test_known_vectors(dut):
    operand_pairs = [
        (0x00, 0x00),
        (0x00, 0x01),
        (0x01, 0x00),
        (0x7F, 0x01),
        (0x80, 0x01),
        (0xFE, 0x01),
        (0xFF, 0x01),
        (0xAA, 0x55),
        (0x96, 0x3C),
        (0xD7, 0xD7),
    ]

    vector_index = 0
    for a, b in operand_pairs:
        for op in range(8):
            await _drive_and_check(
                dut,
                a,
                b,
                op,
                context=f"known vector {vector_index}",
            )
            vector_index += 1


@cocotb.test()
async def test_random_stress(dut):
    rng = random.Random(_DV_SEED ^ 0xA8A5_31E7)
    vectors = []

    for op in range(8):
        for _ in range(32):
            vectors.append((rng.getrandbits(8), rng.getrandbits(8), op))

    vectors.extend(
        (rng.getrandbits(8), rng.getrandbits(8), rng.randrange(8))
        for _ in range(768)
    )
    rng.shuffle(vectors)

