@cocotb.test()
async def test_combinational_sustained_activity(dut):
    """Drive one complete operation per 50 MHz integration-context cycle."""
    rng = random.Random(_DV_SEED ^ 0xC01B_A8A5)
    operations = list(range(8))
    operations.extend(rng.randrange(8) for _ in range(504))

