@cocotb.test()
async def test_throughput_measure(dut):
    """Measure combinational retirements in 50 MHz context-cycle units."""
    rng = random.Random(_DV_SEED ^ 0x7A12_A8F4)
    n_ops = 32
    retirement_cycles = []

    for cycle in range(n_ops):
        dut.a.value = int(rng.getrandbits(8))
        dut.b.value = int(rng.getrandbits(8))
        dut.op.value = int(rng.randrange(8))
        await Timer(_SETTLE_NS, unit="ns")
        int(dut.result.value)
        retirement_cycles.append(cycle)
        await Timer(
            _CONTEXT_CLOCK_PERIOD_NS - _SETTLE_NS,
            unit="ns",
        )

    cyc_per_op = (
        retirement_cycles[-1] - retirement_cycles[0]
    ) / (n_ops - 1)

    with open("throughput_measured.json", "w", encoding="utf-8") as artifact:
